package com.wms.repository;
import com.wms.model.entity.TransferOrder; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface TransferOrderRepository extends JpaRepository<TransferOrder,Long> { @Query("select distinct t from TransferOrder t join fetch t.sourceWarehouse join fetch t.targetWarehouse left join fetch t.lines l left join fetch l.item order by t.createdAt desc") List<TransferOrder> findAllDetailed(); @Query("select distinct t from TransferOrder t join fetch t.sourceWarehouse join fetch t.targetWarehouse left join fetch t.lines l left join fetch l.item where t.id=:id") Optional<TransferOrder> findDetailedById(@Param("id") Long id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select t from TransferOrder t where t.id=:id") Optional<TransferOrder> findForUpdateById(@Param("id") Long id); }
